import{at as e,it as t,o as n,vt as r}from"./chunks/framework.DQt_9H6f.js";var i=JSON.parse(`{"title":"LaTeX diff","description":"","frontmatter":{},"headers":[],"relativePath":"guide/latex-diff.md","filePath":"guide/latex-diff.md"}`),a={name:`guide/latex-diff.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="latex-diff" tabindex="-1">LaTeX diff <a class="header-anchor" href="#latex-diff" aria-label="Permalink to “LaTeX diff”">​</a></h1><p><code>latexdiff</code> marks what changed between two versions of a LaTeX document: additions in blue, deletions in red. TeXRA uses it in two places.</p><h2 id="ask-the-assistant" tabindex="-1">Ask the assistant <a class="header-anchor" href="#ask-the-assistant" aria-label="Permalink to “Ask the assistant”">​</a></h2><p>There is no diff panel. Ask in plain words, and the assistant runs <code>latexdiff</code> (or <code>latexdiff-vc</code> against a git commit) in the shell and compiles the result:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Write the latexdiff from old.tex to new.tex into diff.tex and compile it.</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Show me a latexdiff PDF of main.tex against the last commit.</span></span></code></pre></div><p>Run a formatter (<code>latexindent</code> or <code>tex-fmt</code>) on both versions first: consistent indentation and line breaks keep <code>latexdiff</code> from marking whitespace.</p><h2 id="edit-previews" tabindex="-1">Edit previews <a class="header-anchor" href="#edit-previews" aria-label="Permalink to “Edit previews”">​</a></h2><p>When an edit to a <code>.tex</code> file waits for your approval, TeXRA can show it as a compiled latexdiff. Two settings under <strong>Settings → LaTeX</strong> shape that preview:</p><ul><li><strong>Math markup in diffs</strong> (<code>texra.latexdiff.mathMarkup</code>): how changes inside math environments are marked.</li><li><strong>Only changed pages in diff PDFs</strong> (<code>texra.latexdiff.changesOnly</code>): keep only the pages that hold a change.</li></ul><p><code>latexdiff</code> needs a TeX distribution; read <a href="./installation.html">Installation</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><ul><li><a href="./workflows/polish-a-draft.html">Polish a draft</a></li><li><a href="./latex-tools.html">LaTeX tools</a></li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};